// Only named story checkpoints may write during isolated boss encounters.
function saveBlocked(options={}){
 if(campaignWorld&&!options.illustratedCheckpoint)return 'Use Save inside Konoha.';
 if($('menu').style.display!=='none')return 'No active game.';
 if(sandbox)return 'Sandbox: temporary progress, no saving.';
 if(importBusy&&!options.importCommit)return 'Import in progress.';
 if(valleyFinal()||mentorLesson()||['sasukeEnd','jiraiyaEnd','jiraiyaRetry'].includes(mistScene?.name))return 'Finish the current story sequence first.';
 if(arenaIsolationAt!==null&&!options.checkpoint)return 'Boss encounter in progress. Your last checkpoint is protected.';
 return '';
}
function save(silent=false,options={}){
 const blocked=saveBlocked(options);if(blocked){if(!silent)msg(blocked);return false;}
 if(recoveryPending&&silent&&!options.confirmRecovery){$('saveState').textContent='Backup restored · save to confirm';return false;}
 try{const state=snapshot(options.checkpoint===true);writeSave(state);if(validIllustratedPosition(returnIllustrated)){try{localStorage.setItem(ILLUSTRATED_POSITION,JSON.stringify({signature:positionSignature(state),position:returnIllustrated}));}catch{}}recoveryPending=false;$('continue').disabled=false;refreshRecovery();$('saveState').textContent='Local save';if(!silent)msg('Game saved.');return true;}catch(e){$('saveState').textContent='Unsaved · export a backup';if(!silent)msg('Could not save. Use Export.');return false;}
}
function start(restore){if(importBusy)return;returnIllustrated=null;$('start').dataset.confirm='';$('start').textContent='New Game';audio.unlock();if(restore){try{const s=readSave(DATA.enemies.length);if(!s){$('error').textContent='No saved game found.';return;}applySave(s);}catch(e){$('error').textContent='Invalid save. You can import a backup.';return;}}else reset();$('error').textContent='';$('saveState').textContent=restore?'Save restored':'New game · unsaved';running=true;audio.wind(true);clearInput();$('menu').style.display='none';$('pause').textContent='II';msg(restore?'Save restored.':'Find Kakashi in the square.');if(canEnterIllustrated(true)&&showModal('pause')&&!openIllustrated(true,restore))closeModal();}
$('start').onclick=()=>{if(!$('continue').disabled&&$('start').dataset.confirm!=='yes'){$('start').dataset.confirm='yes';$('start').textContent='Confirm New Game';$('error').textContent='The new game will replace your save when saved. Export a backup from Continue to keep it.';return;}$('start').dataset.confirm='';$('start').textContent='New Game';start(false);};$('continue').onclick=()=>start(true);$('save').onclick=()=>save(false);
$('export').onclick=()=>{const reason=saveBlocked();if(reason){msg(reason);return;}try{exportSave(snapshot());msg('Save backup exported.');}catch(e){msg('Export failed.')}};
$('import').onclick=$('importMenu').onclick=()=>{if(!sandbox&&!importBusy)$('saveFile').click();};
$('saveFile').onchange=async e=>{if(sandbox||importBusy){e.target.value='';return;}const revision=sessionRevision;importBusy=true;try{audio.unlock();const s=await importSave(e.target.files[0],DATA.enemies.length);if(sandbox||revision!==sessionRevision)throw Error('La sesión cambió durante la importación; volvé a seleccionar el archivo.');if(modal)closeModal();if(rpgUI.opened)rpgUI.close();if(worldUI.opened)worldUI.close();applySave(s);running=true;audio.wind(true);clearInput();$('menu').style.display='none';$('pause').textContent='II';const persisted=save(true,{confirmRecovery:true,importCommit:true});msg(persisted?'Partida importada y guardada.':'Partida importada; almacenamiento bloqueado. Exportá para conservarla.');if(persisted){importBusy=false;returnIllustrated=null;if(canEnterIllustrated(true)&&showModal('pause')&&!openIllustrated(true,false))closeModal();}}catch(err){$('error').textContent='Import failed: '+err.message;msg('Import failed: '+err.message);}finally{importBusy=false;e.target.value='';}};
