function clearWaterPrison(){waterPrison=null;if($('prisonPrompt'))$('prisonPrompt').hidden=true;if($('prisonOrb'))$('prisonOrb').hidden=true;}
function syncPrisonUI(){if(!waterPrison)return;const q=waterPrison,electric=q.kind==='electric',conf=electric?{presses:VALLEY_RULES.shockPresses}:MIST_COMBAT.prison;$('prisonPrompt').dataset.kind=electric?'electric':'water';$('prisonOrb').dataset.kind=electric?'electric':'water';$('prisonHeading').textContent=electric?'LIGHTNING PRISON!':'WATER PRISON!';$('prisonInstruction').textContent=electric?'Alternate rapidly · −10 HP each second':'Alternate the movement keys rapidly';$('prisonPrompt').hidden=false;$('prisonOrb').hidden=false;$('prisonLeft').textContent=actionKey('a');$('prisonRight').textContent=actionKey('d');$('prisonLeft').dataset.next=String(q.next==='a');$('prisonRight').dataset.next=String(q.next==='d');$('prisonFill').style.width=(q.presses/conf.presses*100)+'%';$('prisonTime').textContent=q.left.toFixed(1)+' s · '+q.presses+'/'+conf.presses;}
function trapWater(source){if(waterPrison||mistScene||p.dashGuard>0||p.dashTime>0||p.invuln>0||(p.prisonImmune||0)>0)return false;if(p.substitution>0){playerHurt(1,source);return false;}if(p.pending?.ras){cancelRasengan();}waterPrison={left:MIST_COMBAT.prison.duration,presses:0,next:'a',uiAt:t+.1};p.pending=null;p.anim=null;p.dashTime=0;p.queued=false;p.combo=0;p.motion=false;p.sprinting=false;clearInput();syncPrisonUI();audio.play('charge');msg('WATER PRISON · alternate your movement keys!',4);return true;}
function prisonPress(k){if(!waterPrison||!running||k!==waterPrison.next)return false;const electric=waterPrison.kind==='electric';waterPrison.presses++;waterPrison.next=k==='a'?'d':'a';if(waterPrison.presses>=(electric?VALLEY_RULES.shockPresses:MIST_COMBAT.prison.presses)){clearWaterPrison();p.prisonImmune=MIST_COMBAT.prison.immunity;p.invuln=Math.max(p.invuln||0,.6);effects.push({x:p.x,z:p.z,type:electric?'lightning':'water',r:2.8,life:.5,max:.5,col:C.blue});audio.play('heavy');msg(electric?'LIGHTNING PRISON BROKEN!':'Water Prison broken!');}else syncPrisonUI();return true;}
$('prisonLeft').onclick=()=>prisonPress('a');$('prisonRight').onclick=()=>prisonPress('d');
function trapLightning(b){if(boss!==b||mistScene||waterPrison||valleyFinal())return false;if(p.dashTime>0||p.dashGuard>0){feedback.number(p.x,p.z,'LOCK BROKEN','shield');return false;}p.hp=immortalActive()?p.hp:Math.max(0,p.hp-b.rush.damage);feedback.number(p.x,p.z,immortalActive()?'IMMUNE':b.rush.damage,'player');chargeKyubi(b.rush.damage*COMBAT.kyubi.received);if(!p.hp){startValleyUltimate(b);b.finalDuel.stage='failed';failValley(b);return true;}b.rush=null;if(b.chain){b.cooldowns.chidoriChain=b.chain.cooldown;b.chain=null;}b.attack=1.5;b.motion=b.sprinting=false;p.pending=null;p.anim=null;p.dashTime=0;p.dashGuard=0;p.substitution=0;p.queued=false;p.combo=0;p.motion=p.sprinting=false;clearInput();waterPrison={kind:'electric',left:VALLEY_RULES.shockDuration,clock:1,presses:0,next:'a',uiAt:t+.1};syncPrisonUI();audio.play('blackChidori');feedback.impact(.18,.025);msg('LIGHTNING PRISON · break free before the next shock!',4);return true;}
function tickPrison(dt){p.prisonImmune=Math.max(0,(p.prisonImmune||0)-dt);if(!waterPrison)return;if(waterPrison.kind==='electric'){const q=waterPrison;q.left=Math.max(0,q.left-dt);q.clock-=dt;while(q.clock<=1e-8){q.clock+=1;if(!immortalActive())p.hp=Math.max(0,p.hp-VALLEY_RULES.shockDamage);feedback.number(p.x,p.z,immortalActive()?'IMMUNE':VALLEY_RULES.shockDamage,'player');audio.play('shockTick');feedback.impact(.09,0);if(!p.hp){const b=boss;clearWaterPrison();if(b?.id==='sasuke'){startValleyUltimate(b);b.finalDuel.stage='failed';failValley(b);}return;}}if(q.left<=1e-8){clearWaterPrison();p.invuln=Math.max(p.invuln||0,.6);msg('Lightning Prison dissipated.');}else if(t>=q.uiAt){q.uiAt=t+.1;syncPrisonUI();}return;}waterPrison.left-=dt;if(waterPrison.left<=0){clearWaterPrison();p.prisonImmune=MIST_COMBAT.prison.immunity;p.invuln=0;playerHurt(MIST_COMBAT.prison.failDamage,boss||p);if(boss)msg('Water Prison burst!');}else if(t>=waterPrison.uiAt){waterPrison.uiAt=t+.1;syncPrisonUI();}}
function spawnWaterClones(b){const conf=MIST_COMBAT.clone;for(let i=0;i<conf.count&&mistClones.filter(c=>c.hp>0).length<conf.max;i++){const angle=Math.random()*Math.PI*2,r=2.2+i*.8;const pos=spawnPosition({x:b.x+Math.cos(angle)*r,z:b.z+Math.sin(angle)*r});if(!pos)continue;mistClones.push({...pos,id:'water-clone-'+(++mistCloneSerial),kind:'zabuza',waterClone:true,hp:conf.hp,maxHP:conf.hp,life:conf.life,dirX:1,dirZ:0,walk:0,motion:false,flash:0});effects.push({...pos,type:'water',r:1.6,life:.45,max:.45,col:C.blue});}}
function tickWaterClones(dt){const conf=MIST_COMBAT.clone;for(const c of mistClones){if(c.hp<=0)continue;c.life-=dt;c.flash=Math.max(0,c.flash-dt);if(c.life<=0){c.hp=0;continue;}const v=directionToward(p.x-c.x,p.z-c.z);c.dirX=v.x;c.dirZ=v.z;c.motion=true;move(c,v.x*conf.speed*dt,v.z*conf.speed*dt);c.walk+=dt*10;if(dist(c,p)<conf.reach&&trapWater(c)){c.hp=0;effects.push({x:c.x,z:c.z,type:'water',r:1.5,life:.4,max:.4,col:C.blue});}}mistClones=mistClones.filter(c=>c.hp>0&&c.life>0);}
function launchNeedles(origin,count,damage){const v=directionToward(p.x-origin.x,p.z-origin.z),base=Math.atan2(v.z,v.x),conf=MIST_COMBAT.mirror;for(let i=0;i<count&&projectiles.length<conf.projectileCap;i++){const angle=base+(i-(count-1)/2)*.115;projectiles.push({x:origin.x,z:origin.z,dx:Math.cos(angle),dz:Math.sin(angle),life:1.7,speed:conf.needleSpeed,hostile:true,kind:'iceNeedle',damage});}}
function teleportHaku(b,exclude=null){const mirrors=mistMirrors.filter(m=>m.hp>0&&m.id!==exclude&&m.id!==b.lastMirror&&dist(m,b)>1.1);if(!mirrors.length)return false;const m=mirrors[Math.floor(Math.random()*mirrors.length)],v=directionToward(ARENA.x-m.x,ARENA.z-m.z);effects.push({x:b.x,z:b.z,type:'ice',r:1.3,life:.3,max:.3,col:C.blue});b.x=m.x+v.x*.7;b.z=m.z+v.z*.7;b.lastMirror=m.id;effects.push({x:b.x,z:b.z,type:'ice',r:1.3,life:.3,max:.3,col:C.blue});return true;}
