 if(b.id==='sasuke'&&b.independent&&a.projectile){const count=a.projectile==='fire'?1:a.projectile==='wing'?7:5,available=Math.max(0,VALLEY_RULES.projectileCap-projectiles.filter(q=>q.valley&&q.life>0).length),base=Math.atan2(a.dz,a.dx);for(let i=0;i<Math.min(count,available);i++){const ang=base+(i-(count-1)/2)*.16+((a.pulse||1)===2?.08:0);projectiles.push({x:b.x+Math.cos(ang)*.8,z:b.z+Math.sin(ang)*.8,dx:Math.cos(ang),dz:Math.sin(ang),life:a.projectile==='fire'?1.65:1.45,speed:a.projectile==='fire'?13:17,hostile:true,valley:true,kind:a.projectile==='fire'?'fire':'valleyBlade',damage:a.damage});}audio.play(a.projectile==='fire'?'charge':'shuriken');return;}
