 if(a.special==='dragon'){const v=a.dx!==undefined?directionToward(a.dx,a.dz):directionToward(p.x-b.x,p.z-b.z),cfg=MIST_COMBAT.dragon;projectiles.push({x:b.x,z:b.z,dx:v.x,dz:v.z,dragonWake:true,wake:[],wakeDist:0,life:cfg.life,speed:cfg.speed,hostile:true,kind:'water',homing:true,damage:a.damage});audio.play('heavy');}
